package com.ecommerce.product.service; import org.springframework.web.bind.annotation.*; import org.springframework.http.*; import java.time.*; import java.util.*; @RestControllerAdvice public class ApiExceptionHandler { @ExceptionHandler(NoSuchElementException.class) ResponseEntity<?> notFound(Exception e){return ResponseEntity.status(404).body(Map.of("timestamp",Instant.now(),"error","NOT_FOUND","message",e.getMessage()));} @ExceptionHandler(IllegalArgumentException.class) ResponseEntity<?> bad(Exception e){return ResponseEntity.badRequest().body(Map.of("timestamp",Instant.now(),"error","BAD_REQUEST","message",e.getMessage()));} @ExceptionHandler(IllegalStateException.class) ResponseEntity<?> state(Exception e){return ResponseEntity.status(409).body(Map.of("timestamp",Instant.now(),"error","CONFLICT","message",e.getMessage()));} }